package com.pulsepay.payment;
import com.fasterxml.jackson.databind.ObjectMapper; import com.pulsepay.common.ApiException; import com.pulsepay.idempotency.IdempotencyService; import com.pulsepay.security.MerchantPrincipal; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/payment-intents") public class PaymentController {
 private final JdbcTemplate db; private final ObjectMapper json; private final IdempotencyService idempotency; public PaymentController(JdbcTemplate db,ObjectMapper json,IdempotencyService idempotency){this.db=db;this.json=json;this.idempotency=idempotency;}
 record Create(long amountMinor,String currency,String description,UUID customerId,Map<String,Object> metadata){}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> create(@AuthenticationPrincipal MerchantPrincipal p,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Create r){if(r.amountMinor()<=0||r.currency()==null||!r.currency().matches("[A-Z]{3}"))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_AMOUNT_OR_CURRENCY","amount_minor must be positive and currency must be ISO-4217 uppercase.");var replay=idempotency.replayOrClaim(p.merchantId(),"payment_intent.create",key,r);if(replay.isPresent())return replay.get();
  if(r.customerId()!=null){Integer count=db.queryForObject("select count(*) from customers where id=? and merchant_id=?",Integer.class,r.customerId(),p.merchantId());if(count==null||count==0)throw new ApiException(HttpStatus.NOT_FOUND,"CUSTOMER_NOT_FOUND","Customer was not found.");}UUID id=UUID.randomUUID();String publicId="pi_"+id.toString().replace("-","");db.update("insert into payment_intents(id,public_id,merchant_id,customer_id,amount_minor,currency,description,status,metadata) values(?,?,?,?,?,?,?,'REQUIRES_CONFIRMATION',cast(? as jsonb))",id,publicId,p.merchantId(),r.customerId(),r.amountMinor(),r.currency(),r.description(),write(r.metadata()));Map<String,Object> out=external(byPublic(p,publicId));idempotency.complete(p.merchantId(),"payment_intent.create",key,out);audit(p,"payment_intent.created",id);return out;}
 @GetMapping public List<Map<String,Object>> list(@AuthenticationPrincipal MerchantPrincipal p,@RequestParam(required=false)String status,@RequestParam(required=false)String currency,@RequestParam(required=false)String query,@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestParam(defaultValue="created_at")String sortBy,@RequestParam(defaultValue="desc")String sortDirection,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="50")int size){int boundedPage=Math.max(1,page),boundedSize=Math.max(1,Math.min(100,size));String orderField="amount".equals(sortBy)?"amount_minor":"created_at";String direction="asc".equalsIgnoreCase(sortDirection)?"asc":"desc";String fromDate=date(from),toDate=date(to);if(fromDate!=null&&toDate!=null&&fromDate.compareTo(toDate)>0)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_DATE_RANGE","The start date must be on or before the end date.");String sql="select public_id,amount_minor,currency,status,description,created_at from payment_intents where merchant_id=? and (? is null or status=?) and (? is null or currency=?) and (? is null or public_id ilike ? or coalesce(description,'') ilike ?) and (? is null or created_at>=cast(? as date)) and (? is null or created_at<cast(? as date)+interval '1 day') order by "+orderField+" "+direction+", public_id asc limit ? offset ?";return db.query(sql,(rs,i)->Map.of("id",rs.getString(1),"amount_minor",rs.getLong(2),"currency",rs.getString(3),"status",rs.getString(4),"description",Optional.ofNullable(rs.getString(5)).orElse(""),"created_at",rs.getTimestamp(6).toInstant().toString()),p.merchantId(),blank(status),blank(status),blank(currency),blank(currency),blank(query),wildcard(query),wildcard(query),fromDate,fromDate,toDate,toDate,boundedSize,(boundedPage-1)*boundedSize);}
 @GetMapping("/{id}") public Map<String,Object> one(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id){return external(byPublic(p,id));}
 @GetMapping("/{id}/details") public Map<String,Object> details(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id){Map<String,Object> payment=byPublic(p,id);UUID internalId=(UUID)payment.get("internal_id");Map<String,Object> result=external(payment);var authorization=db.query("select id,authorized_minor,captured_minor,status,created_at,updated_at from authorizations where payment_intent_id=?",(rs,i)->Map.<String,Object>of("id",rs.getObject(1).toString(),"authorized_minor",rs.getLong(2),"captured_minor",rs.getLong(3),"status",rs.getString(4),"created_at",rs.getTimestamp(5).toInstant().toString(),"updated_at",rs.getTimestamp(6).toInstant().toString()),internalId);result.put("authorization",authorization.isEmpty()?null:authorization.getFirst());result.put("captures",db.query("select c.id,c.amount_minor,c.status,c.created_at from captures c join authorizations a on a.id=c.authorization_id where a.payment_intent_id=? order by c.created_at",(rs,i)->Map.<String,Object>of("id",rs.getObject(1).toString(),"amount_minor",rs.getLong(2),"status",rs.getString(3),"created_at",rs.getTimestamp(4).toInstant().toString()),internalId));result.put("refunds",db.query("select public_id,amount_minor,currency,status,created_at from refunds where merchant_id=? and payment_intent_id=? order by created_at",(rs,i)->Map.<String,Object>of("id",rs.getString(1),"amount_minor",rs.getLong(2),"currency",rs.getString(3),"status",rs.getString(4),"created_at",rs.getTimestamp(5).toInstant().toString()),p.merchantId(),internalId));result.put("ledger_entries",db.query("select j.transaction_reference,a.name,e.debit_minor,e.credit_minor,j.currency,j.posted_at from ledger_entries e join ledger_journals j on j.id=e.journal_id join ledger_accounts a on a.id=e.account_id where j.merchant_id=? and (j.transaction_reference=? or exists (select 1 from refunds r where r.payment_intent_id=? and j.transaction_reference='refund:'||r.id::text)) order by j.posted_at",(rs,i)->Map.<String,Object>of("journal",rs.getString(1),"account",rs.getString(2),"debit_minor",rs.getLong(3),"credit_minor",rs.getLong(4),"currency",rs.getString(5),"posted_at",rs.getTimestamp(6).toInstant().toString()),p.merchantId(),"payment:"+internalId,internalId));result.put("timeline",db.query("select action,created_at from audit_logs where merchant_id=? and resource_id=? order by created_at",(rs,i)->Map.<String,Object>of("action",rs.getString(1),"created_at",rs.getTimestamp(2).toInstant().toString()),p.merchantId(),internalId));return result;}
 @PostMapping("/{id}/confirm") @Transactional public Map<String,Object> confirm(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key){var replay=idempotency.replayOrClaim(p.merchantId(),"payment_intent.confirm:"+id,key,Map.of());if(replay.isPresent())return replay.get();Map<String,Object> x=byPublic(p,id);String state=(String)x.get("status");if(!PaymentStateMachine.canConfirm(state))throw new ApiException(HttpStatus.CONFLICT,"INVALID_PAYMENT_STATE","This payment cannot be confirmed in its current state.");UUID uuid=(UUID)x.get("internal_id");db.update("update payment_intents set status='PROCESSING',updated_at=now(),version=version+1 where id=?",uuid);db.update("insert into outbox_events(merchant_id,aggregate_type,aggregate_id,event_type,correlation_id,payload)values(?,'payment_intent',?,'payment.processing',gen_random_uuid(),cast(? as jsonb))",p.merchantId(),uuid,write(Map.of("payment_intent_id",id)));audit(p,"payment_intent.confirmed",uuid);Map<String,Object> out=external(byPublic(p,id));idempotency.complete(p.merchantId(),"payment_intent.confirm:"+id,key,out);return out;}
 @PostMapping("/{id}/cancel") @Transactional public Map<String,Object> cancel(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id){Map<String,Object>x=byPublic(p,id);if(!Set.of("REQUIRES_CONFIRMATION","REQUIRES_PAYMENT_METHOD").contains(x.get("status")))throw new ApiException(HttpStatus.CONFLICT,"INVALID_PAYMENT_STATE","Only unprocessed payments can be cancelled.");db.update("update payment_intents set status='CANCELED',updated_at=now() where id=?",x.get("internal_id"));audit(p,"payment_intent.cancelled",(UUID)x.get("internal_id"));return external(byPublic(p,id));}
 Map<String,Object> byPublic(MerchantPrincipal p,String publicId){var rows=db.query("select id,public_id,amount_minor,currency,status,description,created_at,updated_at from payment_intents where merchant_id=? and public_id=?",(rs,i)->{Map<String,Object>m=new LinkedHashMap<>();m.put("internal_id",UUID.fromString(rs.getString(1)));m.put("id",rs.getString(2));m.put("amount_minor",rs.getLong(3));m.put("currency",rs.getString(4));m.put("status",rs.getString(5));m.put("description",rs.getString(6));m.put("created_at",rs.getTimestamp(7).toInstant().toString());m.put("updated_at",rs.getTimestamp(8).toInstant().toString());return m;},p.merchantId(),publicId);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"PAYMENT_NOT_FOUND","Payment intent was not found.");return rows.getFirst();}
 private Map<String,Object> external(Map<String,Object> value){Map<String,Object> copy=new LinkedHashMap<>(value);copy.remove("internal_id");return copy;}
 private String blank(String value){return value==null||value.isBlank()?null:value;} private String date(String value){if(value==null||value.isBlank())return null;try{return java.time.LocalDate.parse(value).toString();}catch(Exception error){throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_DATE_RANGE","Dates must use ISO-8601 YYYY-MM-DD format.");}} private String wildcard(String value){return value==null||value.isBlank()?null:"%"+value.replace("%","\\%").replace("_","\\_")+"%";}
 private String write(Object v){try{return json.writeValueAsString(v==null?Map.of():v);}catch(Exception e){throw new IllegalStateException(e);}} private void audit(MerchantPrincipal p,String action,UUID id){db.update("insert into audit_logs(merchant_id,actor_user_id,action,resource_type,resource_id)values(?,?,?,'payment_intent',?)",p.merchantId(),p.userId(),action,id);}
}
